// Orca's plugin frames get no permissions, so the async Clipboard API is refused, but
// execCommand('copy') during a click still works (plugin-frame-session-policies.ts in Orca).
function copyText(text) {
  var area = el('textarea')
  area.value = text
  area.setAttribute('readonly', '')
  area.style.position = 'fixed'
  area.style.top = '-1000px'
  area.style.opacity = '0'
  document.body.appendChild(area)
  area.select()
  var copied = false
  try {
    copied = document.execCommand('copy')
  } catch (_) {}
  document.body.removeChild(area)
  return copied
}

