// Asks the worker for its data, reading Entire first unless the focused workspace's entry is
// younger than maxAgeMs (0 always reads). Orca starts the worker if it isn't running.
function ask(maxAgeMs, manual) {
  if (!orca.host.has('plugin.request')) {
    readError = { code: 'unknown_method', message: 'this Orca has no plugin.request. Entire for Orca needs Orca 1.4.246 or later.' }
    return rerender()
