// When the panel mounts and when focus moves to another workspace or branch, it asks the worker for
// data, which reads Entire only if what it has for the workspace is over a minute old. The
// minute's rerender asks again once the shown entry is 5 minutes old.
function noteFocus(context, entry) {
  var key = context
    ? JSON.stringify([
        context.displayName,
        context.branch,
        context.terminals
          .map(function (terminal) {
            return terminal.id
          })
          .sort()
      ])
    : null
  var age = entry ? Date.now() - Date.parse(entry.at) : Infinity
  if (key !== focusedKey) {
    focusedKey = key
    readError = null
    if (key && !(age < SWITCH_FRESH_MS)) ask(SWITCH_FRESH_MS)
  } else if (key && entry && reads === 0 && !readError && !(age < AUTO_REFRESH_MS)) {
    ask(AUTO_REFRESH_MS)
  }
}

