    return
  }
  orca.host.call('workspace.readContext', {}).then(
    function (context) {
      render(context, null)
    },
    function (error) {
      render(null, error)
    }
  )
}

if (orca.plugin) orca.plugin.on('entire.changed', fetchData)
// Each new subscriber first gets the current context, so this also renders the first view.
if (orca.api.minor >= 2) {
  orca.on('workspace.changed', function (event) {
    render(event.context, null)
  })
} else {
  tick()
}
