17	  return { files: count(/(\d+) files? changed/), additions: count(/(\d+) insertions?/), deletions: count(/(\d+) deletions?/) }
18	}
19	
20	// The branch's changes against its base, as Entire's web view shows them. Null when git can't tell.
21	export async function diffStat(host, base, { signal } = {}) {
22	  for (const ref of [`origin/${base}`, base]) {
23	    const result = await runGit(host, ['diff', '--shortstat', `${ref}...HEAD`], { signal }).catch(() => null)
24	    if (result?.code === 0) return parseShortstat(result.stdout)
25	  }
26	  return null
27	}
